import{_ as a,o as e,c as r,a4 as i}from"./chunks/framework.BybBnFXO.js";const p=JSON.parse('{"title":"同色宝石判别","description":"","frontmatter":{"title":"同色宝石判别","identification":"same-color-gems"},"headers":[],"relativePath":"zh/identification/same-color-gems.md","filePath":"zh/identification/same-color-gems.md","lastUpdated":1785888308000}'),o={name:"zh/identification/same-color-gems.md"};function d(l,t,n,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="同色宝石判别" tabindex="-1">同色宝石判别 <a class="header-anchor" href="#同色宝石判别" aria-label="Permalink to &quot;同色宝石判别&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>同一种颜色可能对应多种宝石——红色可能是红宝石、尖晶石、石榴石或玻璃。 结合 RI / SG / 多色性 / 包裹体，可把同色宝石逐一排除。以下流程图 覆盖红色、蓝色、绿色三大最易混淆家族。</p><h2 id="判别流程" tabindex="-1">判别流程 <a class="header-anchor" href="#判别流程" aria-label="Permalink to &quot;判别流程&quot;">​</a></h2><div><pre class="mermaid">flowchart TD
  A[红色宝石] --&gt; B{折射率 RI}
  B --&gt;|1.76| C[刚玉族]
  C --&gt; D{紫外荧光}
  D --&gt;|强红| E[红宝石 Ruby]
  D --&gt;|弱| F[需光谱确认]
  B --&gt;|1.71-1.72| G[尖晶石 Spinel]
  B --&gt;|1.74-1.89| H[石榴石 Garnet]
  B --&gt;|1.5-1.7 玻璃感| I{气泡/流动纹?}
  I --&gt;|有| J[玻璃仿品]
  I --&gt;|无| K[复查折射仪]
</pre></div><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>红：红宝石 RI 1.76 + 强红荧光；尖晶石 1.71–1.72 无荧光；石榴石 1.74–1.89。</li><li>蓝：蓝宝石 1.76 无多色性二色；坦桑石 1.69–1.70 强三色性；堇青石 1.54 三色性极强。</li><li>绿：祖母绿 1.57–1.58（浸油裂隙）；翠榴石 1.89 高色散；橄榄石 1.65–1.69（双影）。</li><li>荧光是筛分关键：天然红宝石 LW 强红，合成焰熔法常更强且带白色调。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>ruby</td><td>RI 1.76 + red fluor.</td><td>—</td></tr><tr><td>sapphire</td><td>RI 1.76, no pleochroism</td><td>—</td></tr><tr><td>emerald</td><td>RI 1.57 + oil fissures</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>`,10)])])}const f=a(o,[["render",d]]);export{p as __pageData,f as default};
